// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint64 lockBlock, address actor, bytes32 g) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        lockBlock = uint64(bound(uint256(lockBlock), block.number + 1, block.number + 100000));
        vm.roll(lockBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // Rule: after lockInGuess at block B, settling at any block > B+... must not revert
        vm.roll(lockBlock + 2);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
